{
  "name": "B&K Precision 9100系列可编程直流电源",
  "name_en": "B&K Precision 9100 Series Programmable DC Power Supply",
  "manufacturer": "B&K Precision",
  "description": "这是一款台式可编程直流电源，可输出并调节稳定的直流电压与电流，用于电子器件供电、原型电路测试、实验室台架测量以及需要远程控制电源输出的自动化实验。",
  "description_en": "This is a benchtop programmable DC power supply that provides regulated DC voltage and current. It is used for powering electronic devices, testing prototype circuits, bench measurements, and automated laboratory setups requiring remote control of power output.",
  "tag_hints": [
    "programmable DC power supply",
    "benchtop power supply",
    "voltage/current sourcing",
    "remote sense",
    "electronic test equipment",
    "automated lab power control"
  ],
  "actions": [
    {
      "action_name": "auto-float_to_4_dig",
      "description": "将数值转换为设备使用的4位设定格式。",
      "description_en": "Convert a value into the 4-digit setting format used by the device."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化电源，使其进入可远程控制的准备状态。",
      "description_en": "Initialize the power supply so it is ready for remote control."
    },
    {
      "action_name": "auto-lock_front_panel",
      "description": "锁定或解锁电源前面板按键与操作。",
      "description_en": "Lock or unlock the front-panel controls of the power supply."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量输出电流。",
      "description_en": "Measure the output current."
    },
    {
      "action_name": "auto-measure_power",
      "description": "测量输出功率。",
      "description_en": "Measure the output power."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量输出电压。",
      "description_en": "Measure the output voltage."
    },
    {
      "action_name": "auto-remote_sense",
      "description": "启用或禁用远端电压感测功能。",
      "description_en": "Enable or disable remote voltage sensing."
    },
    {
      "action_name": "auto-select_channel",
      "description": "选择要控制或测量的输出通道。",
      "description_en": "Select the output channel to control or measure."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置输出电流设定值。",
      "description_en": "Set the output current setpoint."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置输出电压设定值。",
      "description_en": "Set the output voltage setpoint."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "打开或关闭电源输出。",
      "description_en": "Turn the power output on or off."
    }
  ]
}

